<?php
/**
 * Per-type admin forms (forms/admin-<type>.json) generated by older cli/schema-build.php runs.
 * Nothing reads them (the admin uses forms/admin-product.json for every type) and their bare
 * "options_from": "categories" is not a valid BBF 2.2 source, so BBF check.php reports them.
 * A file counts as generated only if its top-level "product_type" equals <type>; hand-written
 * forms (admin-product, admin-page, ...) never carry that key.
 */
final class ObsoleteAdminForms
{
    /** @return list<string> paths relative to $root, e.g. "forms/admin-simple.json" */
    public static function find(string $root): array
    {
        $found = [];
        foreach (glob($root . '/forms/admin-*.json') ?: [] as $file) {
            if (!is_file($file) || is_link($file)) {
                continue;
            }
            $type = substr(basename($file, '.json'), strlen('admin-'));
            $form = json_decode((string)file_get_contents($file), true);
            if (is_array($form) && ($form['product_type'] ?? null) === $type) {
                $found[] = 'forms/' . basename($file);
            }
        }
        sort($found, SORT_STRING);
        return $found;
    }
}
